You can use a simple loop to prompt the user for input and check against the options. Here's a basic example:
import java.util.Scanner;

public class Game {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        String[] choices = {"left", "right"};
        System.out.println("Do you want to go left or right?");
        String input = scanner.nextLine().toLowerCase();

        while (!input.equals("left") && !input.equals("right")) {
            System.out.println("Invalid choice. Please enter left or right.");
            input = scanner.nextLine().toLowerCase();
        }

        if (input.equals("left")) {
            System.out.println("You chose left.");
        } else {
            System.out.println("You chose right.");
        }

        scanner.close();
    }
}
